   destIFolder->GetParent(getter_AddRefs(parentFolder));
@@ -1840,16 +1853,18 @@ nsresult nsParseNewMailState::MoveIncorporatedMessage(nsIMsgDBHdr* mailHdr,
     return NS_MSG_NOT_A_MAIL_FOLDER;
