   rv = localFolder->GetDatabaseWOReparse(getter_AddRefs(destMailDB));
-  NS_WARNING_ASSERTION(destMailDB && NS_SUCCEEDED(rv),
-                       "failed to open mail db parsing folder");
+  NS_ENSURE_SUCCESS(rv, rv);
+  if (!destMailDB) {
+    return NS_ERROR_UNEXPECTED;
